:root {
  /* ==========================================
     LINE 圆润布局 + 黑白反转配色
     对方 = 黑色，我 = 白色
     ========================================== */

  /* ----- 顶部导航栏 (纯白，简洁) ----- */
  --chat-header-bg: #ffffff;
  --chat-header-blur: 0px;
  --chat-header-border: rgba(0, 0, 0, 0.06);
  --chat-header-title-color: #1c1c1e;
  --chat-header-title-size: 17px;
  --chat-header-title-weight: 600;
  --chat-header-subtitle-color: #8e8e93;
  --chat-header-subtitle-size: 12px;
  --chat-header-icon-color: #1c1c1e;
  --chat-header-avatar-border: 2px solid #e5e5ea;

  /* ----- 我方消息气泡 (白色) ----- */
  --bubble-me-bg: #ffffff;
  --bubble-me-color: #1c1c1e;
  --bubble-me-font-size: 15px;
  --bubble-me-padding: 10px 14px;
  --bubble-me-radius: 16px;
  --bubble-me-radius-first: 16px 16px 4px 16px;
  --bubble-me-radius-mid: 16px 4px 4px 16px;
  --bubble-me-radius-last: 16px 4px 16px 16px;
  --bubble-me-shadow: 0 1px 4px rgba(0, 0, 0, 0.06);
  --bubble-me-border: 1px solid #e5e5ea;

  /* ----- 对方消息气泡 (黑色) ----- */
  --bubble-them-bg: #1c1c1e;
  --bubble-them-color: #ffffff;
  --bubble-them-font-size: 15px;
  --bubble-them-padding: 10px 14px;
  --bubble-them-radius: 16px;
  --bubble-them-radius-first: 16px 16px 16px 4px;
  --bubble-them-radius-mid: 4px 16px 16px 4px;
  --bubble-them-radius-last: 4px 16px 16px 16px;
  --bubble-them-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
  --bubble-them-border: none;

  --chat-message-max-width: 78%;

  /* ----- 底部输入区 (纯白) ----- */
  --input-area-bg: #ffffff;
  --input-area-blur: 0px;
  --input-area-border-top: 1px solid #e5e5ea;
  --input-area-padding: 12px 16px;
  --input-area-min-height: 56px;

  --input-box-bg: #f2f2f5;
  --input-box-color: #1c1c1e;
  --input-box-placeholder: #8e8e93;
  --input-box-radius: 20px;
  --input-box-padding: 10px 18px;
  --input-box-font-size: 15px;
  --input-box-border: none;
  --input-box-shadow: none;

  /* 发送按钮 (黑色) —— 与对方气泡呼应 */
  --send-btn-bg: #1c1c1e;
  --send-btn-color: #ffffff;
  --send-btn-size: 32px;
  --send-btn-radius: 50%;
  --send-btn-shadow: 0 2px 6px rgba(0, 0, 0, 0.15);
  --send-btn-bg-hover: #3a3a3c;

  --plus-btn-color: #8e8e93;
  --input-btn-color: #8e8e93;

  /* ----- 时间戳 & 日期 (柔和灰) ----- */
  --timestamp-color: #8e8e93;
  --timestamp-size: 11px;

  --date-divider-bg: rgba(60, 60, 67, 0.08);
  --date-divider-color: #8e8e93;
  --date-divider-size: 11px;
  --date-divider-radius: 100px;
  --date-divider-padding: 4px 12px;

  /* ----- 已读状态 (灰色) ----- */
  --status-color: #8e8e93;
  --status-size: 10px;
  --status-read-color: #8e8e93;


}
:root {
  /* ===== 翻译 ===== */
  --translation-text-color: #8e8e93;
  --translation-btn-color: #8e8e93;
  --translation-bg: rgba(60, 60, 67, 0.04);

  /* ===== 旁白 ===== */
  --narration-color: #3a3a3c;
}
:root {
  /* ===== 引用块 me/them 分化 ===== */
  --reply-them-text-color: #ffffff;
  --reply-them-name-color: #ffffff;
  --reply-them-bg: rgba(255, 255, 255, 0.08);

  --reply-me-text-color: #1c1c1e;
  --reply-me-name-color: #1c1c1e;
  --reply-me-bg: rgba(0, 0, 0, 0.04);
}
:root {
  /* ===== 图片消息（表情包）无边框 ===== */
  --image-msg-border: none;
  --image-msg-radius: 0px;        /* 完全直角，更像原生表情包 */
  --image-msg-shadow: none;       /* 去掉阴影，更干净 */
}

